def taller_within(a: list[int], k: int) -> list[int]:
    n = len(a)
    if k == 0:
        return [0] * n
    uniq = sorted(set(a))
    rank_of = {value: index + 1 for index, value in enumerate(uniq)}
    m = len(uniq)
    bit = [0] * (m + 1)

    def add(index: int, delta: int) -> None:
        while index <= m:
            bit[index] += delta
            index += index & -index

    def prefix(index: int) -> int:
        total = 0
        while index:
            total += bit[index]
            index -= index & -index
        return total

    answer = [0] * n
    for i, height in enumerate(a):
        rank = rank_of[height]
        answer[i] = prefix(m) - prefix(rank)
        add(rank, 1)
        if i >= k:
            add(rank_of[a[i - k]], -1)
    return answer
